-- 支出类一级分类：购物
INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) VALUES (0, '购物', NULL, 'expense', 1, 0);

-- 支出类二级分类：外卖
INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) 
SELECT 0, '外卖', id, 'expense', 1, 0 FROM ledger_categories WHERE ledgerId = 0 AND name = '购物' AND parentId IS NULL;

-- 支出类三级分类：饿了么、美团
INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) 
SELECT 0, '饿了么', id, 'expense', 1, 0 FROM ledger_categories WHERE ledgerId = 0 AND name = '外卖';

INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) 
SELECT 0, '美团', id, 'expense', 2, 0 FROM ledger_categories WHERE ledgerId = 0 AND name = '外卖';

-- 收入类一级分类：工资
INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) VALUES (0, '工资', NULL, 'income', 1, 0);

-- 收入类二级分类：主业收入
INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) 
SELECT 0, '主业收入', id, 'income', 1, 0 FROM ledger_categories WHERE ledgerId = 0 AND name = '工资' AND parentId IS NULL;

-- 收入类三级分类：固定工资、绩效奖金
INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) 
SELECT 0, '固定工资', id, 'income', 1, 0 FROM ledger_categories WHERE ledgerId = 0 AND name = '主业收入';

INSERT INTO ledger_categories (ledgerId, name, parentId, type, sortOrder, createdBy) 
SELECT 0, '绩效奖金', id, 'income', 2, 0 FROM ledger_categories WHERE ledgerId = 0 AND name = '主业收入';

